"use strict";(globalThis.webpackChunkgrc||=[]).push([[32535],{70398(e){e.exports=JSON.parse('{"citeKey":"byna2008taxonomydata","slug":"byna-2008-taxonomy-data-49d6","title":"A Taxonomy of Data Prefetching Mechanisms","authors":["S. Byna","Y. Chen","X.-H. Sun"],"venue":"The International Symposium on Parallel Architectures, Algorithms, and Networks (I-SPAN)","type":"Conference","entryType":"inproceedings","date":"May, 2008","year":2008,"era":"iit","month":5,"doi":"10.1109/i-span.2008.24","abstract":"Data prefetching has been considered an effective way to mask data access latency caused by cache misses and to bridge the performance gap between processor and memory. With hardware and/or software support, data prefetching brings data closer to a processor before it is actually needed. Many prefetching techniques have been proposed in the last few years to reduce data access latency by taking advantage of multi-core architectures. In this paper, we propose a taxonomy that classifies various design concerns in developing a prefetching strategy. We discuss various prefetching strategies and issues that have to be considered in designing a prefetching strategy for multi-core processors.","hasAbstract":true,"lede":"We propose a taxonomy that classifies various design concerns in developing a prefetching strategy.","links":{"pdf":"https://grc.iit.edu/papers/2008/byna-2008-taxonomy-data-49d6.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["byna-surendra","sun-xian-he"]}')}}]);